const body = $json.body ?? $json;
const periodStart = String(body.periodStart ?? '').trim();
const periodEnd = String(body.periodEnd ?? '').trim();
const targetClosedDeals = Number(body.targetClosedDeals ?? 0);
const targetContracts = Number(body.targetContracts ?? 0);
const targetLeads = Number(body.targetLeads ?? 0);
const targetQualifiedLeads = Number(body.targetQualifiedLeads ?? 0);
if (!periodStart || !periodEnd) throw new Error('periodStart and periodEnd are required');
if (new Date(periodStart).getTime() > new Date(periodEnd).getTime()) throw new Error('periodStart must be before periodEnd');
for (const [name,value] of Object.entries({targetClosedDeals,targetContracts,targetLeads,targetQualifiedLeads})) if (!Number.isFinite(value) || value < 0) throw new Error(name + ' must be non-negative');
return [{ json: { periodStart, periodEnd, targetClosedDeals, targetContracts, targetLeads, targetQualifiedLeads, requestedAt: new Date().toISOString() } }];

const ctx = $json.data ?? $json;
const forecast = Array.isArray(ctx.sourceForecasts) ? ctx.sourceForecasts : [];
const capacity = ctx.capacity ?? {};
if (!forecast.length && !Object.keys(capacity).length) throw new Error('No valid forecast or capacity data available for the requested period');
return [{ json: { forecast, capacity, periodStart: $('Normalize Capacity Target Request').first().json.periodStart, periodEnd: $('Normalize Capacity Target Request').first().json.periodEnd, targetClosedDeals: $('Normalize Capacity Target Request').first().json.targetClosedDeals, targetContracts: $('Normalize Capacity Target Request').first().json.targetContracts, targetLeads: $('Normalize Capacity Target Request').first().json.targetLeads, targetQualifiedLeads: $('Normalize Capacity Target Request').first().json.targetQualifiedLeads } }];

const forecast = $json.forecast;
const num = v => Number.isFinite(Number(v)) ? Number(v) : 0;
const projected = forecast.reduce((a,s) => {
  const periods = Array.isArray(s.forecast) ? s.forecast : [];
  for (const p of periods) { a.leads += num(p.projectedLeads); a.qualifiedLeads += num(p.projectedQualifiedLeads); a.contracts += num(p.projectedContracts); a.closedDeals += num(p.projectedClosedDeals); }
  return a;
}, { leads:0, qualifiedLeads:0, contracts:0, closedDeals:0 });
const targets = { leads: num($json.targetLeads), qualifiedLeads: num($json.targetQualifiedLeads), contracts: num($json.targetContracts), closedDeals: num($json.targetClosedDeals) };
const gaps = { leads: Math.max(0, targets.leads - projected.leads), qualifiedLeads: Math.max(0, targets.qualifiedLeads - projected.qualifiedLeads), contracts: Math.max(0, targets.contracts - projected.contracts), closedDeals: Math.max(0, targets.closedDeals - projected.closedDeals) };
const rates = { leadToQualified: projected.leads ? projected.qualifiedLeads / projected.leads : 0, leadToContract: projected.leads ? projected.contracts / projected.leads : 0, contractToClose: projected.contracts ? projected.closedDeals / projected.contracts : 0 };
const actions = [];
if (gaps.leads > 0) actions.push({ priority: 'high', action: 'increase_lead_acquisition', metric: 'leads', gap: Number(gaps.leads.toFixed(2)), rationale: 'Projected lead volume is below target' });
if (gaps.qualifiedLeads > 0) actions.push({ priority: 'high', action: 'improve_lead_qualification', metric: 'qualifiedLeads', gap: Number(gaps.qualifiedLeads.toFixed(2)), rationale: 'Projected qualified-lead volume is below target' });
if (gaps.contracts > 0) actions.push({ priority: 'medium', action: 'improve_offer_and_conversion_process', metric: 'contracts', gap: Number(gaps.contracts.toFixed(2)), rationale: 'Projected contracts are below target' });
if (gaps.closedDeals > 0) actions.push({ priority: 'high', action: 'increase_pipeline_and_closing_capacity', metric: 'closedDeals', gap: Number(gaps.closedDeals.toFixed(2)), rationale: 'Projected closed deals are below target' });
if (!actions.length) actions.push({ priority: 'low', action: 'maintain_current_acquisition_capacity', metric: 'all_targets', gap: 0, rationale: 'Projected pipeline meets or exceeds requested targets' });
const capacityFlags = { acquisitionCapacity: Boolean($json.capacity.acquisitionCapacity), salesCapacity: Boolean($json.capacity.salesCapacity), dispositionCapacity: Boolean($json.capacity.dispositionCapacity) };
return [{ json: { periodStart: $json.periodStart, periodEnd: $json.periodEnd, targets, projected, gaps, conversionRates: rates, capacityFlags, actions, status: actions.some(a => a.priority === 'high') ? 'capacity_gap' : actions.some(a => a.priority === 'medium') ? 'optimization_needed' : 'on_track', analyzedAt: new Date().toISOString() } }];
